def halaman_offset(hal: int, per: int = 20):
    hal = max(1, hal)
    return {'offset': (hal - 1) * per, 'limit': per}
# cursor (suapan infiniti, stabil semasa sisip!):
def halaman_cursor(id_akhir: int | None, per: int = 20):
    return {'selepas': id_akhir, 'had': per}
# SQL: WHERE id > :selepas ORDER BY id LIMIT :had
